const config = {
  "previewFeatures": [],
  "clientVersion": "7.9.1",
  "engineVersion": "e922089b7d7502aff4249d5da3420f6fa55fc6ad",
  "activeProvider": "mysql",
  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"mysql\"\n}\n\n// ─── Access Control ───────────────────────────────────────────────────────────\n\nenum Role {\n  ADMIN\n  MANAGER\n  CASHIER\n  INVENTORY_STAFF\n}\n\nmodel User {\n  id               Int      @id @default(autoincrement())\n  username         String   @unique @db.VarChar(50)\n  passwordHash     String   @db.VarChar(255)\n  fullName         String   @db.VarChar(100)\n  role             Role\n  isActive         Boolean  @default(true)\n  allowedTerminals String?  @db.Text\n  createdAt        DateTime @default(now())\n  updatedAt        DateTime @updatedAt\n\n  permissions  UserPermission[]\n  sessions     RefreshToken[]\n  sales        Sale[]\n  auditLogs    AuditLog[]\n  openedShifts Shift[]          @relation(\"ShiftOpenedBy\")\n  closedShifts Shift[]          @relation(\"ShiftClosedBy\")\n\n  @@index([username])\n}\n\nmodel UserPermission {\n  id      Int     @id @default(autoincrement())\n  userId  Int\n  module  String  @db.VarChar(50)\n  action  String  @db.VarChar(50)\n  granted Boolean @default(true)\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, module, action])\n  @@index([userId])\n}\n\nmodel RefreshToken {\n  id        Int      @id @default(autoincrement())\n  token     String   @unique @db.VarChar(512)\n  userId    Int\n  expiresAt DateTime\n  revoked   Boolean  @default(false)\n  createdAt DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n}\n\n// ─── Catalog ──────────────────────────────────────────────────────────────────\n\nmodel Category {\n  id        Int        @id @default(autoincrement())\n  name      String     @unique @db.VarChar(100)\n  createdAt DateTime   @default(now())\n  medicines Medicine[]\n}\n\nmodel Manufacturer {\n  id        Int        @id @default(autoincrement())\n  name      String     @unique @db.VarChar(150)\n  createdAt DateTime   @default(now())\n  medicines Medicine[]\n}\n\nmodel Medicine {\n  id                   Int      @id @default(autoincrement())\n  productCode          String?  @unique @db.VarChar(50)\n  barcode              String?  @db.VarChar(100)\n  brandName            String   @db.VarChar(150)\n  genericName          String?  @db.VarChar(150)\n  strength             String?  @db.VarChar(50)\n  dosageForm           String?  @db.VarChar(50)\n  packSize             String?  @db.VarChar(50)\n  unit                 String?  @db.VarChar(30)\n  taxRate              Decimal  @default(0) @db.Decimal(5, 2)\n  reorderLevel         Int      @default(0)\n  prescriptionRequired Boolean  @default(false)\n  isActive             Boolean  @default(true)\n  categoryId           Int?\n  manufacturerId       Int?\n  createdAt            DateTime @default(now())\n  updatedAt            DateTime @updatedAt\n\n  category     Category?     @relation(fields: [categoryId], references: [id])\n  manufacturer Manufacturer? @relation(fields: [manufacturerId], references: [id])\n  batches      Batch[]\n\n  @@index([barcode])\n  @@index([brandName])\n  @@index([genericName])\n  @@index([productCode])\n}\n\nmodel Batch {\n  id           Int       @id @default(autoincrement())\n  medicineId   Int\n  batchNumber  String    @db.VarChar(100)\n  mfgDate      DateTime?\n  expiryDate   DateTime\n  purchaseRate Decimal   @db.Decimal(10, 2)\n  saleRate     Decimal   @db.Decimal(10, 2)\n  quantity     Int       @default(0)\n  freeQuantity Int       @default(0)\n  supplierId   Int?\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n\n  medicine            Medicine             @relation(fields: [medicineId], references: [id])\n  supplier            Supplier?            @relation(fields: [supplierId], references: [id])\n  saleItems           SaleItem[]\n  purchaseItems       PurchaseItem[]\n  saleReturnItems     SaleReturnItem[]\n  purchaseReturnItems PurchaseReturnItem[]\n  stockMovements      StockMovement[]\n\n  @@index([medicineId])\n  @@index([expiryDate])\n  @@index([batchNumber])\n}\n\n// ─── Parties ──────────────────────────────────────────────────────────────────\n\nmodel Customer {\n  id                 Int      @id @default(autoincrement())\n  name               String   @db.VarChar(150)\n  phone              String?  @db.VarChar(20)\n  address            String?  @db.Text\n  creditLimit        Decimal  @default(0) @db.Decimal(12, 2)\n  outstandingBalance Decimal  @default(0) @db.Decimal(12, 2)\n  isActive           Boolean  @default(true)\n  createdAt          DateTime @default(now())\n  updatedAt          DateTime @updatedAt\n\n  sales        Sale[]\n  payments     Payment[]\n  salesReturns SaleReturn[]\n\n  @@index([name])\n  @@index([phone])\n}\n\nmodel Supplier {\n  id             Int      @id @default(autoincrement())\n  name           String   @db.VarChar(150)\n  contactPerson  String?  @db.VarChar(100)\n  phone          String?  @db.VarChar(20)\n  address        String?  @db.Text\n  payableBalance Decimal  @default(0) @db.Decimal(12, 2)\n  isActive       Boolean  @default(true)\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  purchases       Purchase[]\n  payments        Payment[]\n  batches         Batch[]\n  purchaseReturns PurchaseReturn[]\n\n  @@index([name])\n}\n\n// ─── Sales ────────────────────────────────────────────────────────────────────\n\nenum SaleStatus {\n  DRAFT\n  COMPLETED\n  CANCELLED\n}\n\nenum PaymentMethod {\n  CASH\n  CARD\n  CREDIT\n  SPLIT\n}\n\nmodel Sale {\n  id             Int           @id @default(autoincrement())\n  invoiceNumber  String        @unique @db.VarChar(50)\n  customerId     Int?\n  userId         Int\n  terminalId     String?       @db.VarChar(50)\n  status         SaleStatus    @default(COMPLETED)\n  subtotal       Decimal       @db.Decimal(12, 2)\n  discountAmount Decimal       @default(0) @db.Decimal(12, 2)\n  taxAmount      Decimal       @default(0) @db.Decimal(12, 2)\n  total          Decimal       @db.Decimal(12, 2)\n  amountPaid     Decimal       @db.Decimal(12, 2)\n  changeAmount   Decimal       @default(0) @db.Decimal(12, 2)\n  paymentMethod  PaymentMethod @default(CASH)\n  notes          String?       @db.Text\n  createdAt      DateTime      @default(now())\n\n  shiftId Int?\n  shift   Shift? @relation(fields: [shiftId], references: [id])\n\n  customer Customer?    @relation(fields: [customerId], references: [id])\n  user     User         @relation(fields: [userId], references: [id])\n  items    SaleItem[]\n  returns  SaleReturn[]\n  payments Payment[]\n\n  @@index([invoiceNumber])\n  @@index([customerId])\n  @@index([createdAt])\n}\n\nmodel Shift {\n  id             Int       @id @default(autoincrement())\n  openedAt       DateTime  @default(now())\n  closedAt       DateTime?\n  openingBalance Decimal   @default(0) @db.Decimal(12, 2)\n  closingBalance Decimal?  @db.Decimal(12, 2)\n  status         String    @default(\"OPEN\") @db.VarChar(10)\n  notes          String?   @db.Text\n  openedById     Int\n  closedById     Int?\n\n  openedBy User   @relation(\"ShiftOpenedBy\", fields: [openedById], references: [id])\n  closedBy User?  @relation(\"ShiftClosedBy\", fields: [closedById], references: [id])\n  sales    Sale[]\n\n  @@index([status])\n  @@index([openedAt])\n}\n\nmodel SaleItem {\n  id       Int     @id @default(autoincrement())\n  saleId   Int\n  batchId  Int\n  quantity Int\n  saleRate Decimal @db.Decimal(10, 2)\n  discount Decimal @default(0) @db.Decimal(5, 2)\n  taxRate  Decimal @default(0) @db.Decimal(5, 2)\n  total    Decimal @db.Decimal(12, 2)\n\n  sale  Sale  @relation(fields: [saleId], references: [id], onDelete: Cascade)\n  batch Batch @relation(fields: [batchId], references: [id])\n\n  @@index([saleId])\n}\n\nmodel SaleReturn {\n  id           Int      @id @default(autoincrement())\n  saleId       Int\n  customerId   Int?\n  reason       String   @db.Text\n  refundAmount Decimal  @db.Decimal(12, 2)\n  refundMethod String?  @db.VarChar(50)\n  createdAt    DateTime @default(now())\n\n  sale     Sale             @relation(fields: [saleId], references: [id])\n  customer Customer?        @relation(fields: [customerId], references: [id])\n  items    SaleReturnItem[]\n\n  @@index([saleId])\n}\n\nmodel SaleReturnItem {\n  id           Int     @id @default(autoincrement())\n  saleReturnId Int\n  batchId      Int\n  quantity     Int\n  isDamaged    Boolean @default(false)\n  refundAmount Decimal @db.Decimal(12, 2)\n\n  saleReturn SaleReturn @relation(fields: [saleReturnId], references: [id], onDelete: Cascade)\n  batch      Batch      @relation(fields: [batchId], references: [id])\n\n  @@index([saleReturnId])\n}\n\n// ─── Purchasing ───────────────────────────────────────────────────────────────\n\nenum PurchaseStatus {\n  DRAFT\n  RECEIVED\n  PARTIAL\n}\n\nmodel Purchase {\n  id             Int            @id @default(autoincrement())\n  invoiceNumber  String         @unique @db.VarChar(50)\n  supplierId     Int\n  status         PurchaseStatus @default(RECEIVED)\n  subtotal       Decimal        @db.Decimal(12, 2)\n  discountAmount Decimal        @default(0) @db.Decimal(12, 2)\n  taxAmount      Decimal        @default(0) @db.Decimal(12, 2)\n  total          Decimal        @db.Decimal(12, 2)\n  amountPaid     Decimal        @default(0) @db.Decimal(12, 2)\n  notes          String?        @db.Text\n  purchaseDate   DateTime       @default(now())\n  createdAt      DateTime       @default(now())\n  updatedAt      DateTime       @updatedAt\n\n  supplier Supplier         @relation(fields: [supplierId], references: [id])\n  items    PurchaseItem[]\n  returns  PurchaseReturn[]\n  payments Payment[]\n\n  @@index([supplierId])\n  @@index([purchaseDate])\n}\n\nmodel PurchaseItem {\n  id           Int     @id @default(autoincrement())\n  purchaseId   Int\n  batchId      Int\n  quantity     Int\n  freeQuantity Int     @default(0)\n  purchaseRate Decimal @db.Decimal(10, 2)\n  saleRate     Decimal @db.Decimal(10, 2)\n  discount     Decimal @default(0) @db.Decimal(5, 2)\n  taxRate      Decimal @default(0) @db.Decimal(5, 2)\n  total        Decimal @db.Decimal(12, 2)\n\n  purchase Purchase @relation(fields: [purchaseId], references: [id], onDelete: Cascade)\n  batch    Batch    @relation(fields: [batchId], references: [id])\n\n  @@index([purchaseId])\n}\n\nmodel PurchaseReturn {\n  id          Int      @id @default(autoincrement())\n  purchaseId  Int\n  supplierId  Int\n  reason      String   @db.Text\n  totalAmount Decimal  @db.Decimal(12, 2)\n  createdAt   DateTime @default(now())\n\n  purchase Purchase             @relation(fields: [purchaseId], references: [id])\n  supplier Supplier             @relation(fields: [supplierId], references: [id])\n  items    PurchaseReturnItem[]\n\n  @@index([purchaseId])\n}\n\nmodel PurchaseReturnItem {\n  id               Int     @id @default(autoincrement())\n  purchaseReturnId Int\n  batchId          Int\n  quantity         Int\n  amount           Decimal @db.Decimal(12, 2)\n\n  purchaseReturn PurchaseReturn @relation(fields: [purchaseReturnId], references: [id], onDelete: Cascade)\n  batch          Batch          @relation(fields: [batchId], references: [id])\n\n  @@index([purchaseReturnId])\n}\n\n// ─── Finance ──────────────────────────────────────────────────────────────────\n\nenum PaymentType {\n  CUSTOMER_RECEIPT\n  SUPPLIER_PAYMENT\n  EXPENSE\n  INCOME\n}\n\nmodel Payment {\n  id         Int         @id @default(autoincrement())\n  type       PaymentType\n  amount     Decimal     @db.Decimal(12, 2)\n  method     String?     @db.VarChar(50)\n  reference  String?     @db.VarChar(100)\n  notes      String?     @db.Text\n  customerId Int?\n  supplierId Int?\n  saleId     Int?\n  purchaseId Int?\n  createdAt  DateTime    @default(now())\n\n  customer Customer? @relation(fields: [customerId], references: [id])\n  supplier Supplier? @relation(fields: [supplierId], references: [id])\n  sale     Sale?     @relation(fields: [saleId], references: [id])\n  purchase Purchase? @relation(fields: [purchaseId], references: [id])\n\n  @@index([customerId])\n  @@index([supplierId])\n  @@index([createdAt])\n}\n\nmodel Expense {\n  id          Int      @id @default(autoincrement())\n  category    String   @db.VarChar(100)\n  description String?  @db.Text\n  amount      Decimal  @db.Decimal(12, 2)\n  date        DateTime @default(now())\n  createdAt   DateTime @default(now())\n\n  @@index([date])\n}\n\nmodel Income {\n  id          Int      @id @default(autoincrement())\n  category    String   @db.VarChar(100)\n  description String?  @db.Text\n  amount      Decimal  @db.Decimal(12, 2)\n  date        DateTime @default(now())\n  createdAt   DateTime @default(now())\n\n  @@index([date])\n}\n\n// ─── Inventory ────────────────────────────────────────────────────────────────\n\nenum MovementType {\n  SALE\n  SALE_RETURN\n  PURCHASE\n  PURCHASE_RETURN\n  ADJUSTMENT_IN\n  ADJUSTMENT_OUT\n  DAMAGE\n  EXPIRY_WRITEOFF\n}\n\nmodel StockMovement {\n  id          Int          @id @default(autoincrement())\n  batchId     Int\n  type        MovementType\n  quantity    Int\n  reason      String?      @db.VarChar(255)\n  referenceId Int?\n  createdAt   DateTime     @default(now())\n\n  batch Batch @relation(fields: [batchId], references: [id])\n\n  @@index([batchId])\n  @@index([createdAt])\n}\n\n// ─── System ───────────────────────────────────────────────────────────────────\n\nmodel AuditLog {\n  id         Int      @id @default(autoincrement())\n  userId     Int?\n  module     String   @db.VarChar(50)\n  action     String   @db.VarChar(100)\n  recordId   Int?\n  oldValue   Json?\n  newValue   Json?\n  terminalId String?  @db.VarChar(50)\n  createdAt  DateTime @default(now())\n\n  user User? @relation(fields: [userId], references: [id], onDelete: SetNull)\n\n  @@index([userId])\n  @@index([module])\n  @@index([createdAt])\n}\n\nmodel Setting {\n  id        Int      @id @default(autoincrement())\n  key       String   @unique @db.VarChar(100)\n  value     String   @db.Text\n  updatedAt DateTime @updatedAt\n}\n\nmodel Backup {\n  id        Int      @id @default(autoincrement())\n  filename  String   @db.VarChar(255)\n  size      BigInt?\n  status    String   @db.VarChar(20)\n  location  String?  @db.VarChar(500)\n  createdAt DateTime @default(now())\n}\n\nmodel License {\n  id              Int       @id @default(autoincrement())\n  licenseKey      String    @unique @db.VarChar(500)\n  customerId      String?   @db.VarChar(100)\n  storeName       String    @db.VarChar(150)\n  plan            String    @db.VarChar(50)\n  maxPos          Int       @default(1)\n  activationDate  DateTime?\n  expiryDate      DateTime?\n  features        Json?\n  status          String    @db.VarChar(20)\n  lastValidatedAt DateTime?\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n}\n"
}

